     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.NewReservation;
     5	import br.com.marealta.domain.RatePlan;
     6	import com.fasterxml.jackson.databind.JsonNode;
     7	import com.fasterxml.jackson.databind.ObjectMapper;
     8	import java.time.LocalDate;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.regex.Pattern;
    11	
    12	final class RequestParser {
    13	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    14	
    15	    private RequestParser() {}
    16	
    17	    static NewReservation reservation(ObjectMapper mapper, String body) {
    18	        JsonNode json;
    19	        try {
    20	            json = mapper.readTree(body);
    21	        } catch (Exception e) {
    22	            throw DomainException.invalid("O corpo não é um JSON válido");
    23	        }
    24	        if (json == null || !json.isObject()) {
    25	            throw DomainException.invalid("O corpo deve ser um objeto JSON");
    26	        }
    27	        int roomNumber = integer(json, "roomNumber");
    28	        String name = text(json, "guestName");
    29	        String email = text(json, "guestEmail");
    30	        String cpf = text(json, "guestCpf");
    31	        LocalDate checkIn = date(json, "checkIn");
    32	        LocalDate checkOut = date(json, "checkOut");
    33	        int guests = integer(json, "guests");
    34	        RatePlan plan;
    35	        try {
    36	            plan = RatePlan.valueOf(text(json, "ratePlan"));
    37	        } catch (IllegalArgumentException e) {
    38	            throw DomainException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
    39	        }
    40	        return new NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
    41	    }
    42	
    43	    private static String text(JsonNode json, String field) {
    44	        JsonNode node = json.get(field);
    45	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    46	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
    47	        }
    48	        return node.asText().trim();
    49	    }
    50	
    51	    private static int integer(JsonNode json, String field) {
    52	        JsonNode node = json.get(field);
    53	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    54	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
    55	        }
    56	        return node.asInt();
    57	    }
    58	
    59	    private static LocalDate date(JsonNode json, String field) {
    60	        String raw = text(json, field);
    61	        if (!DATE.matcher(raw).matches()) {
    62	            throw DomainException.invalid("Data inválida em " + field + " (use AAAA-MM-DD)");
    63	        }
    64	        try {
    65	            return LocalDate.parse(raw);
    66	        } catch (DateTimeParseException e) {
    67	            throw DomainException.invalid("Data inválida em " + field);
    68	        }
    69	    }
    70	}
