     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.ReservationService;
     5	import br.com.marealta.report.CsvRenderer;
     6	import br.com.marealta.report.Report;
     7	import br.com.marealta.store.Store;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	import io.javalin.Javalin;
    10	import io.javalin.http.Context;
    11	import io.javalin.http.HttpStatus;
    12	import java.util.List;
    13	import java.util.Map;
    14	
    15	public final class Routes {
    16	    private static final org.slf4j.Logger LOG = org.slf4j.LoggerFactory.getLogger(Routes.class);
    17	
    18	    private Routes() {}
    19	
    20	    public static void register(Javalin app, ObjectMapper mapper, ReservationService service, Store store,
    21	                                List<Report> reports) {
    22	        app.get("/rooms", ctx -> ctx.json(service.rooms()));
    23	
    24	        app.post("/reservations", ctx -> ctx.status(HttpStatus.CREATED)
    25	                .json(service.create(RequestParser.reservation(mapper, ctx.body()))));
    26	        app.get("/reservations/{id}", ctx -> ctx.json(service.get(id(ctx))));
    27	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(service.confirm(id(ctx))));
    28	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(service.cancel(id(ctx))));
    29	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(service.checkIn(id(ctx))));
    30	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
    31	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
    32	
    33	        app.get("/messages", ctx -> ctx.json(service.messages()));
    34	
    35	        for (Report report : reports) {
    36	            app.get("/reports/" + report.name(), ctx -> {
    37	                String csv = CsvRenderer.render(store.tx(tx -> report.build(tx, ctx.queryParam(report.param()))));
    38	                ctx.contentType("text/csv; charset=utf-8").result(csv);
    39	            });
    40	        }
    41	
    42	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    43	        app.exception(Exception.class, (e, ctx) -> {
    44	            LOG.error("Erro inesperado", e);
    45	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    46	        });
    47	        app.error(404, ctx -> {
    48	            if (ctx.result() == null || ctx.result().isEmpty()) {
    49	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
    50	            }
    51	        });
    52	    }
    53	
    54	    private static long id(Context ctx) {
    55	        String raw = ctx.pathParam("id");
    56	        try {
    57	            return Long.parseLong(raw);
    58	        } catch (NumberFormatException e) {
    59	            throw DomainException.reservationNotFound(raw);
    60	        }
    61	    }
    62	
    63	    private static void error(Context ctx, int status, String code, String message) {
    64	        ctx.status(status).json(Map.of("error", code, "message", message));
    65	    }
    66	}
