     1	package br.com.marealta.domain;
     2	
     3	import br.com.marealta.store.Store;
     4	import br.com.marealta.store.Tx;
     5	import java.math.BigDecimal;
     6	import java.util.List;
     7	
     8	public class ReservationService {
     9	    private static final String CHANNEL_EMAIL = "EMAIL";
    10	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    11	
    12	    private final Store store;
    13	
    14	    public ReservationService(Store store) {
    15	        this.store = store;
    16	    }
    17	
    18	    public List<Room> rooms() {
    19	        return store.tx(Tx::rooms);
    20	    }
    21	
    22	    public List<Message> messages() {
    23	        return store.tx(Tx::messages);
    24	    }
    25	
    26	    public Reservation get(long id) {
    27	        return store.tx(tx -> load(tx, id, false));
    28	    }
    29	
    30	    public Reservation create(NewReservation req) {
    31	        if (!req.checkOut().isAfter(req.checkIn())) {
    32	            throw DomainException.invalid("A saída deve ser depois da entrada");
    33	        }
    34	        if (req.guests() < 1) {
    35	            throw DomainException.invalid("É preciso ao menos um hóspede");
    36	        }
    37	        return store.tx(tx -> {
    38	            Room room = tx.room(req.roomNumber(), true)
    39	                    .orElseThrow(() -> DomainException.roomNotFound(req.roomNumber()));
    40	            if (req.guests() > room.capacity()) {
    41	                throw DomainException.capacity("O quarto " + room.number() + " comporta até "
    42	                        + room.capacity() + " pessoas");
    43	            }
    44	            if (tx.overlaps(room.number(), req.checkIn(), req.checkOut())) {
    45	                throw DomainException.unavailable("O quarto " + room.number() + " já está reservado nesse período");
    46	            }
    47	            Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
    48	            return tx.insert(new Reservation(0, room.number(), req.guestName(), req.guestEmail(), req.guestCpf(),
    49	                    req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote.nights(), quote.subtotal(),
    50	                    quote.discount(), quote.total(), Status.PENDING, Money.ZERO, null));
    51	        });
    52	    }
    53	
    54	    public Reservation confirm(long id) {
    55	        return store.tx(tx -> {
    56	            Reservation r = load(tx, id, true);
    57	            requireStatus(r, "confirmada", Status.PENDING);
    58	            Reservation confirmed = r.confirmed();
    59	            tx.update(confirmed);
    60	            String text = ReceiptFormatter.text(receipt(tx, confirmed));
    61	            tx.addMessage(CHANNEL_EMAIL, confirmed.guestEmail(), CONFIRMATION_SUBJECT,
    62	                    "Olá, " + confirmed.guestName() + "!\n\n"
    63	                            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    64	                            + text + "\n\n"
    65	                            + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    66	                            + "Até breve!");
    67	            return confirmed;
    68	        });
    69	    }
    70	
    71	    public Reservation cancel(long id) {
    72	        return store.tx(tx -> {
    73	            Reservation r = load(tx, id, true);
    74	            requireStatus(r, "cancelada", Status.PENDING, Status.CONFIRMED);
    75	            BigDecimal refund = r.ratePlan().refundable() ? r.amountPaid() : Money.ZERO;
    76	            Reservation cancelled = r.cancelled(refund);
    77	            tx.update(cancelled);
    78	            return cancelled;
    79	        });
    80	    }
    81	
    82	    public Reservation checkIn(long id) {
    83	        return store.tx(tx -> {
    84	            Reservation r = load(tx, id, true);
    85	            requireStatus(r, "usada para check-in", Status.CONFIRMED);
    86	            Reservation updated = r.withStatus(Status.CHECKED_IN);
    87	            tx.update(updated);
    88	            return updated;
    89	        });
    90	    }
    91	
    92	    public Receipt checkOut(long id) {
    93	        return store.tx(tx -> {
    94	            Reservation r = load(tx, id, true);
    95	            requireStatus(r, "usada para check-out", Status.CHECKED_IN);
    96	            Reservation updated = r.withStatus(Status.CHECKED_OUT);
    97	            tx.update(updated);
    98	            return receipt(tx, updated);
    99	        });
   100	    }
   101	
   102	    /** Segunda via: só existe para reserva paga. */
   103	    public Receipt document(long id) {
   104	        return store.tx(tx -> {
   105	            Reservation r = load(tx, id, false);
   106	            if (!r.status().isPaid()) {
   107	                throw DomainException.notAllowed("A reserva " + id + " não tem comprovante (situação " + r.status() + ")");
   108	            }
   109	            return receipt(tx, r);
   110	        });
   111	    }
   112	
   113	    private static Reservation load(Tx tx, long id, boolean lock) {
   114	        return tx.reservation(id, lock).orElseThrow(() -> DomainException.reservationNotFound(id));
   115	    }
   116	
   117	    private static Receipt receipt(Tx tx, Reservation r) {
   118	        Room room = tx.room(r.roomNumber(), false).orElseThrow(() -> DomainException.roomNotFound(r.roomNumber()));
   119	        return Receipt.of(r, room);
   120	    }
   121	
   122	    private static void requireStatus(Reservation r, String action, Status... allowed) {
   123	        for (Status s : allowed) {
   124	            if (r.status() == s) {
   125	                return;
   126	            }
   127	        }
   128	        throw DomainException.notAllowed("A reserva " + r.id() + " está " + r.status() + " e não pode ser " + action);
   129	    }
   130	}
