=== domain/Pricing.java
     1	package br.com.marealta.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {}
    11	
    12	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    13	    public static boolean isHighSeason(LocalDate night) {
    14	        Month month = night.getMonth();
    15	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    16	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    20	        BigDecimal rate = room.nightlyRate();
    21	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : Money.round(rate);
    22	    }
    23	
    24	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    25	        BigDecimal subtotal = Money.ZERO;
    26	        int nights = 0;
    27	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    28	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    29	            nights++;
    30	        }
    31	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate()));
    32	        BigDecimal total = Money.round(subtotal.subtract(discount));
    33	        return new Quote(nights, subtotal, discount, total);
    34	    }
    35	}
