    30	    public Reservation create(NewReservation req) {
    31	        if (!req.checkOut().isAfter(req.checkIn())) {
    32	            throw DomainException.invalid("A saída deve ser depois da entrada");
    33	        }
    34	        if (req.guests() < 1) {
    35	            throw DomainException.invalid("É preciso ao menos um hóspede");
    36	        }
    37	        return store.tx(tx -> {
    38	            Room room = tx.room(req.roomNumber(), true)
    39	                    .orElseThrow(() -> DomainException.roomNotFound(req.roomNumber()));
    40	            if (req.guests() > room.capacity()) {
    41	                throw DomainException.capacity("O quarto " + room.number() + " comporta até "
    42	                        + room.capacity() + " pessoas");
    43	            }
    44	            if (tx.overlaps(room.number(), req.checkIn(), req.checkOut())) {
    45	                throw DomainException.unavailable("O quarto " + room.number() + " já está reservado nesse período");
    46	            }
    47	            Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
    48	            return tx.insert(new Reservation(0, room.number(), req.guestName(), req.guestEmail(), req.guestCpf(),
    49	                    req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote.nights(), quote.subtotal(),
    50	                    quote.discount(), quote.total(), Status.PENDING, Money.ZERO, null));
    51	        });
    52	    }
    53	
    54	    public Reservation confirm(long id) {
    55	        return store.tx(tx -> {
    56	            Reservation r = load(tx, id, true);
    57	            requireStatus(r, "confirmada", Status.PENDING);
    58	            Reservation confirmed = r.confirmed();
    59	            tx.update(confirmed);
    60	            String text = ReceiptFormatter.text(receipt(tx, confirmed));
    61	            tx.addMessage(CHANNEL_EMAIL, confirmed.guestEmail(), CONFIRMATION_SUBJECT,
    62	                    "Olá, " + confirmed.guestName() + "!\n\n"
    63	                            + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    64	                            + text + "\n\n"
    65	                            + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    66	                            + "Até breve!");
    67	            return confirmed;
    68	        });
    69	    }
    70	
    71	    public Reservation cancel(long id) {
    72	        return store.tx(tx -> {
    73	            Reservation r = load(tx, id, true);
    74	            requireStatus(r, "cancelada", Status.PENDING, Status.CONFIRMED);
    75	            BigDecimal refund = r.ratePlan().refundable() ? r.amountPaid() : Money.ZERO;
    76	            Reservation cancelled = r.cancelled(refund);
    77	            tx.update(cancelled);
    78	            return cancelled;
