    83	        return store.tx(tx -> {
    84	            Reservation r = load(tx, id, true);
    85	            requireStatus(r, "usada para check-in", Status.CONFIRMED);
    86	            Reservation updated = r.withStatus(Status.CHECKED_IN);
    87	            tx.update(updated);
    88	            return updated;
    89	        });
    90	    }
    91	
    92	    public Receipt checkOut(long id) {
    93	        return store.tx(tx -> {
    94	            Reservation r = load(tx, id, true);
    95	            requireStatus(r, "usada para check-out", Status.CHECKED_IN);
    96	            Reservation updated = r.withStatus(Status.CHECKED_OUT);
    97	            tx.update(updated);
    98	            return receipt(tx, updated);
    99	        });
   100	    }
   101	
   102	    /** Segunda via: só existe para reserva paga. */
   103	    public Receipt document(long id) {
   104	        return store.tx(tx -> {
   105	            Reservation r = load(tx, id, false);
   106	            if (!r.status().isPaid()) {
   107	                throw DomainException.notAllowed("A reserva " + id + " não tem comprovante (situação " + r.status() + ")");
   108	            }
   109	            return receipt(tx, r);
   110	        });
   111	    }
   112	
   113	    private static Reservation load(Tx tx, long id, boolean lock) {
   114	        return tx.reservation(id, lock).orElseThrow(() -> DomainException.reservationNotFound(id));
   115	    }
   116	
   117	    private static Receipt receipt(Tx tx, Reservation r) {
