     5	/**
     6	 * Único lugar que dá o formato aos relatórios: título, cabeçalho, linhas e total.
     7	 * Qualquer mudança comum a todos (como uma linha final com a data de emissão) entra aqui.
     8	 */
     9	public final class CsvRenderer {
    10	    public static final String PROPERTY_NAME = "Pousada Maré Alta";
    11	
    12	    private CsvRenderer() {}
    13	
    14	    public static String render(ReportTable table) {
    15	        StringBuilder sb = new StringBuilder();
    16	        line(sb, List.of(PROPERTY_NAME, table.name(), table.period()));
    17	        line(sb, table.header());
    18	        table.rows().forEach(row -> line(sb, row));
    19	        line(sb, table.total());
    20	        return sb.toString();
    21	    }
    22	
    23	    private static void line(StringBuilder sb, List<String> fields) {
    24	        for (int i = 0; i < fields.size(); i++) {
    25	            if (i > 0) {
    26	                sb.append(',');
    27	            }
    28	            sb.append(escape(fields.get(i)));
    29	        }
    30	        sb.append('\n');
    31	    }
    32	
    33	    private static String escape(String field) {
    34	        if (field.contains(",") || field.contains("\"") || field.contains("\n") || field.contains("\r")) {
    35	            return '"' + field.replace("\"", "\"\"") + '"';
    36	        }
    37	        return field;
    38	    }
    39	}
