     8	
     9	final class Periods {
    10	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
    11	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    12	
    13	    private Periods() {}
    14	
    15	    static LocalDate date(String raw) {
    16	        if (raw == null || !DATE.matcher(raw).matches()) {
    17	            throw DomainException.invalid("Informe a data no formato AAAA-MM-DD");
    18	        }
    19	        try {
    20	            return LocalDate.parse(raw);
    21	        } catch (DateTimeParseException e) {
    22	            throw DomainException.invalid("Data inválida: " + raw);
    23	        }
    24	    }
    25	
    26	    static YearMonth month(String raw) {
    27	        if (raw == null || !MONTH.matcher(raw).matches()) {
    28	            throw DomainException.invalid("Informe o mês no formato AAAA-MM");
    29	        }
