     9	/**
    10	 * Taxa de turismo por hóspede por noite. A prefeitura muda o valor todo ano:
    11	 * basta acrescentar uma vigência (data de início, valor) em {@link #standard()}.
    12	 */
    13	public final class TourismTax {
    14	    private final NavigableMap<LocalDate, BigDecimal> ratesByStart = new TreeMap<>();
    15	
    16	    public TourismTax(Map<LocalDate, BigDecimal> ratesByStart) {
    17	        if (ratesByStart.isEmpty()) {
    18	            throw new IllegalArgumentException("É preciso ao menos uma vigência");
    19	        }
    20	        this.ratesByStart.putAll(ratesByStart);
    21	    }
    22	
    23	    public static TourismTax standard() {
    24	        return new TourismTax(Map.of(LocalDate.MIN, new BigDecimal("4.50")));
    25	    }
    26	
    27	    public BigDecimal ratePerGuestNight(LocalDate date) {
    28	        Map.Entry<LocalDate, BigDecimal> entry = ratesByStart.floorEntry(date);
    29	        return entry != null ? entry.getValue() : ratesByStart.firstEntry().getValue();
    30	    }
    31	
    32	    /** Taxa de uma reserva, pela vigência da data de entrada. */
    33	    public BigDecimal forReservation(Reservation r) {
    34	        return Money.round(ratePerGuestNight(r.checkIn()).multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    35	    }
