 13	
 14	/** Armazenamento em memória, usado nos testes. */
 15	public class MemoryStore implements Store {
 16	    private final List<Room> rooms;
 17	    private final List<Reservation> reservations = new ArrayList<>();
 18	    private final List<Message> messages = new ArrayList<>();
 19	
 20	    public MemoryStore(List<Room> rooms) {
 21	        this.rooms = List.copyOf(rooms);
 22	    }
 23	
 24	    @Override
 25	    public synchronized <T> T tx(Function<Tx, T> work) {
 26	        return work.apply(new MemoryTx());
 27	    }
 28	
 29	    private final class MemoryTx implements Tx {
 30	        @Override
 31	        public List<Room> rooms() { return rooms; }
 32	
 33	        @Override
 34	        public Optional<Room> room(int number, boolean lock) {
 35	            return rooms.stream().filter(r -> r.number() == number).findFirst();
 36	        }
 37	
 38	        @Override
 39	        public boolean overlaps(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
 40	            return reservations.stream().anyMatch(r -> r.roomNumber() == roomNumber
 41	                    && r.status() != Status.CANCELLED
 42	                    && r.checkIn().isBefore(checkOut) && checkIn.isBefore(r.checkOut()));
 43	        }
 44	
 45	        @Override
 46	        public Reservation insert(Reservation reservation) {
 47	            Reservation saved = reservation.withId(reservations.size() + 1L);
 48	            reservations.add(saved);
 49	            return saved;
 50	        }
 51	
 52	        @Override
 53	        public Optional<Reservation> reservation(long id, boolean lock) {
 54	            return reservations.stream().filter(r -> r.id() == id).findFirst();
 55	        }
 56	
 57	        @Override
 58	        public void update(Reservation reservation) {
 59	            reservations.replaceAll(r -> r.id() == reservation.id() ? reservation : r);
 60	        }
 61	
 62	        @Override
 63	        public Message addMessage(String channel, String to, String subject, String body) {
 64	            Message m = new Message(messages.size() + 1L, channel, to, subject, body);
 65	            messages.add(m);
 66	            return m;
 67	        }
 68	
 69	        @Override
 70	        public List<Message> messages() { return List.copyOf(messages); }
 71	
 72	        @Override
 73	        public List<Reservation> startingBetween(LocalDate from, LocalDate toExclusive) {
 74	            return reservations.stream()
 75	                    .filter(r -> !r.checkIn().isBefore(from) && r.checkIn().isBefore(toExclusive))
 76	                    .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
 77	                    .toList();
 78	        }
 79	
 80	        @Override
 81	        public List<Reservation> stayingOn(LocalDate night) {
 82	            return reservations.stream()
 83	                    .filter(r -> !r.checkIn().isAfter(night) && night.isBefore(r.checkOut()))
 84	                    .sorted(Comparator.comparingInt(Reservation::roomNumber).thenComparing(Reservation::id))
 85	                    .toList();
 86	        }
 87	    }
 88	}
