 14	import java.time.LocalDate;
 15	import org.junit.jupiter.api.Test;
 16	
 17	class PricingTest {
 18	    private final Room standard = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
 19	
 20	    @Test
 21	    void highSeasonBoundaries() {
 22	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 12, 14)));
 23	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 12, 15)));
 24	        assertTrue(Pricing.isHighSeason(LocalDate.of(2028, 2, 29)));
 25	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 3, 1)));
 26	        assertTrue(Pricing.isHighSeason(LocalDate.of(2027, 7, 31)));
 27	        assertFalse(Pricing.isHighSeason(LocalDate.of(2027, 8, 1)));
 28	    }
 29	
 30	    @Test
 31	    void highSeasonExample() {
 32	        Quote q = Pricing.quote(standard, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), RatePlan.STANDARD);
 33	        assertEquals(2, q.nights());
 34	        assertEquals(new BigDecimal("599.76"), q.total());
 35	    }
 36	
 37	    @Test
 38	    void nightsAreSeasonedIndividually() {
 39	        // noites de 14/12 (normal) e 15/12 (alta)
 40	        Quote q = Pricing.quote(standard, LocalDate.of(2027, 12, 14), LocalDate.of(2027, 12, 16), RatePlan.STANDARD);
 41	        assertEquals(new BigDecimal("549.78"), q.subtotal());
 42	    }
 43	
 44	    @Test
 45	    void nonRefundableDiscountRoundsHalfEven() {
 46	        Quote q = Pricing.quote(standard, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 11), RatePlan.NON_REFUNDABLE);
 47	        // 249.90 * 0.15 = 37.485 -> 37.48 (meio para o par)
 48	        assertEquals(new BigDecimal("37.48"), q.discount());
 49	        assertEquals(new BigDecimal("212.42"), q.total());
 50	    }
 51	
 52	    @Test
 53	    void brlFormat() {
 54	        assertEquals("R$ 1.234,56", Money.brl(new BigDecimal("1234.56")));
 55	        assertEquals("R$ 0,00", Money.brl(Money.ZERO));
 56	    }
 57	}
