 74	
 75	class ApiTest {
 76	    private final ObjectMapper mapper = new ObjectMapper()
 77	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
 78	    private final HttpClient http = HttpClient.newHttpClient();
 79	    private Javalin app;
 80	    private String base;
 81	
 82	    @BeforeEach
 83	    void start() {
 84	        app = App.create(new MemoryStore(Config.initialRooms())).start(0);
 85	        base = "http://localhost:" + app.port();
 86	    }
 87	
 88	    @AfterEach
 89	    void stop() {
 90	        app.stop();
 91	    }
 92	
 93	    private HttpResponse<String> send(String method, String path, String body) throws Exception {
 94	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 95	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 96	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 97	    }
 98	
 99	    private static String booking(int room, String in, String out, int guests, String plan) {
100	        return """
101	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@example.com","guestCpf":"111.222.333-44",
102	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
103	    }
104	
105	    @Test
106	    void moneyIsWrittenWithTwoDecimals() throws Exception {
107	        create(101, "2027-03-10", "2027-03-11", 1, "STANDARD");
108	        String body = send("GET", "/reservations/1", null).body();
109	        assertTrue(body.contains("\"amountPaid\":0.00"), body);
110	        assertTrue(body.contains("\"total\":249.90"), body);
111	        assertTrue(body.contains("\"refund\":null"), body);
112	        assertTrue(body.contains("\"checkIn\":\"2027-03-10\""), body);
113	    }
114	
115	    private JsonNode create(int room, String in, String out, int guests, String plan) throws Exception {
116	        HttpResponse<String> r = send("POST", "/reservations", booking(room, in, out, guests, plan));
117	        assertEquals(201, r.statusCode(), r.body());
118	        return mapper.readTree(r.body());
119	    }
120	
121	    @Test
122	    void roomsAreListed() throws Exception {
123	        JsonNode rooms = mapper.readTree(send("GET", "/rooms", null).body());
124	        assertEquals(5, rooms.size());
125	        assertEquals(249.90, rooms.get(0).get("nightlyRate").asDouble());
126	    }
127	
128	    @Test
129	    void fullLifecycleWithDocumentAndEmail() throws Exception {
130	        JsonNode r = create(201, "2027-03-10", "2027-03-12", 2, "STANDARD");
131	        assertEquals(1, r.get("id").asInt());
132	        assertEquals("PENDING", r.get("status").asText());
133	        assertEquals(0, r.get("amountPaid").decimalValue().signum());
134	        assertTrue(r.get("refund").isNull());
135	        assertEquals(0, new java.math.BigDecimal("779.80").compareTo(r.get("total").decimalValue()));
136	
137	        assertEquals(409, send("GET", "/reservations/1/document", null).statusCode());
138	        assertEquals(409, send("POST", "/reservations/1/check-in", null).statusCode());
139	
140	        JsonNode confirmed = mapper.readTree(send("POST", "/reservations/1/confirmation", null).body());
141	        assertEquals("CONFIRMED", confirmed.get("status").asText());
142	        assertEquals(0, new java.math.BigDecimal("779.80").compareTo(confirmed.get("amountPaid").decimalValue()));
143	        assertEquals(409, send("POST", "/reservations/1/confirmation", null).statusCode());
144	
145	        JsonNode messages = mapper.readTree(send("GET", "/messages", null).body());
146	        assertEquals(1, messages.size());
147	        assertEquals("EMAIL", messages.get(0).get("channel").asText());
148	        assertEquals("Reserva confirmada - Pousada Maré Alta", messages.get(0).get("subject").asText());
149	        assertEquals("""
150	                Olá, Carla Dias!
151	
152	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
153	
154	                Comprovante de reserva nº 1
155	                Hóspede: Carla Dias (CPF 111.222.333-44)
156	                Quarto: 201 (DELUXE)
157	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
158	                Diárias: R$ 779,80
159	                Total: R$ 779,80
160	
161	                A entrada é a partir das 14h, e a saída, até as 12h.
162	                Até breve!""", messages.get(0).get("body").asText());
163	
164	        assertEquals(200, send("GET", "/reservations/1/document", null).statusCode());
165	        assertEquals("CHECKED_IN", mapper.readTree(send("POST", "/reservations/1/check-in", null).body())
166	                .get("status").asText());
167	        assertEquals(409, send("POST", "/reservations/1/cancellation", null).statusCode());
168	        JsonNode doc = mapper.readTree(send("POST", "/reservations/1/check-out", null).body());
169	        assertEquals("Comprovante de reserva", doc.get("title").asText());
170	        assertEquals("DELUXE", doc.get("roomType").asText());
171	        assertEquals(0, doc.get("discount").decimalValue().signum());
172	        assertEquals(1, mapper.readTree(send("GET", "/messages", null).body()).size());
173	    }
174	
175	    @Test
176	    void cancellationRefunds() throws Exception {
177	        create(101, "2027-03-10", "2027-03-11", 1, "STANDARD");
178	        create(102, "2027-03-10", "2027-03-11", 1, "NON_REFUNDABLE");
179	        create(201, "2027-03-10", "2027-03-11", 1, "STANDARD");
180	        send("POST", "/reservations/1/confirmation", null);
181	        send("POST", "/reservations/2/confirmation", null);
182	
183	        assertEquals(0, new java.math.BigDecimal("249.90").compareTo(
184	                mapper.readTree(send("POST", "/reservations/1/cancellation", null).body())
185	                        .get("refund").decimalValue()));
186	        assertEquals(0, mapper.readTree(send("POST", "/reservations/2/cancellation", null).body())
187	                .get("refund").decimalValue().signum());
188	        JsonNode pending = mapper.readTree(send("POST", "/reservations/3/cancellation", null).body());
189	        assertEquals(0, pending.get("refund").decimalValue().signum());
190	        assertEquals(409, send("POST", "/reservations/3/cancellation", null).statusCode());
191	        // quarto liberado pelo cancelamento
192	        create(101, "2027-03-10", "2027-03-11", 1, "STANDARD");
193	    }
194	
195	    @Test
196	    void validationAndConflicts() throws Exception {
197	        assertEquals(400, send("POST", "/reservations", "não é json").statusCode());
198	        assertEquals(400, send("POST", "/reservations", "{}").statusCode());
199	        assertEquals(400, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-10", 1, "STANDARD")).statusCode());
200	        assertEquals(400, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-11", 0, "STANDARD")).statusCode());
201	        assertEquals(400, send("POST", "/reservations", booking(101, "10/03/2027", "2027-03-11", 1, "STANDARD")).statusCode());
202	        assertEquals(400, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-11", 1, "XYZ")).statusCode());
203	        HttpResponse<String> notFound = send("POST", "/reservations", booking(999, "2027-03-10", "2027-03-11", 1, "STANDARD"));
204	        assertEquals(404, notFound.statusCode());
205	        assertEquals("ROOM_NOT_FOUND", mapper.readTree(notFound.body()).get("error").asText());
206	        assertEquals(422, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-11", 3, "STANDARD")).statusCode());
207	
208	        create(101, "2027-03-10", "2027-03-12", 2, "STANDARD");
209	        assertEquals(409, send("POST", "/reservations", booking(101, "2027-03-11", "2027-03-13", 1, "STANDARD")).statusCode());
210	        create(101, "2027-03-12", "2027-03-13", 1, "STANDARD"); // sai e entra no mesmo dia
211	
212	        assertEquals(404, send("GET", "/reservations/99", null).statusCode());
213	        assertEquals(404, send("GET", "/reservations/abc", null).statusCode());
214	        assertEquals(400, send("GET", "/reports/revenue?month=2027-13", null).statusCode());
215	        assertEquals(400, send("GET", "/reports/occupancy", null).statusCode());
216	    }
